version: 1
hostname: fr-router
timezone: Europe/Budapest
interfaces:
  wan: {device: eth0, zone: wan}
  lan: {device: eth1, zone: lan, address: 192.168.1.1/24}
  dmz: {device: eth2, zone: dmz, address: 10.0.2.1/24}
